def run_target(binary: str, token: str, secret: str, timeout: int):
    """Run the target binary and return (returncode, stdout, stderr, timed_out)."""
    cmd = [binary, "--token", token, "--key", secret]
    try:
        proc = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=timeout,
